// spec: .qa/e2e/specs/moderation-menu.md 1.3 · seed: tests/seed.user4.moderation.spec.ts · тикет #4d3a4c (AC 4, 7; реджекты r7/r8), #714b7a (AC 6)
// @data: user4 публикует сторис «QA-AUTO …» (нейтральная картинка tests/stories-viewer/qa-auto-story.jpg) и удаляет её.
// Удержание окна ≥15 с при паузе сторис не проверяем (требование «по времени») — только что окно открыто и «ביטול» оставляет сторис.
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { menuButton } from '../stories-viewer/viewer-helpers';
import { tapIn, appApi, closeApp, iphoneAs, qaText } from './mod-helpers';
import type { Api } from '../_shared/api';

const STORY_IMG = path.resolve(__dirname, '../stories-viewer/qa-auto-story.jpg');

test.describe('בטיחות ומודרציה בצד המשתמש — сторис', () => {
  test('Своя сторис: «פעולות על הסטורי» → «מחיקת הסטורי» → «למחוק את הסטורי?»; «ביטול» — та же сторис, «מחיקה» — удалена @iphone @data (#4d3a4c #714b7a)', async ({ browser }) => {
    test.setTimeout(120_000);
    const page = await iphoneAs(browser, 'user4');
    const caption = qaText('4d3a4c', 'story');
    let api: Api | undefined;
    let storyId = '';
    try {
      api = await appApi(page);
      // Новая сторис как у пользователя: «הסטורי שלי» (без активной сторис) → выбор картинки → /story/new → «שיתוף»
      await expect(page.getByRole('button', { name: /סטורי חדש/ })).toBeVisible();
      const chooser = page.waitForEvent('filechooser');
      await tapIn(page, page.getByRole('button', { name: /הסטורי שלי/ }));
      await (await chooser).setFiles(STORY_IMG);
      await page.waitForURL(/\/story\/new/);
      await page.getByRole('textbox', { name: 'כיתוב (לא חובה)' }).fill(caption);
      const created = page.waitForResponse((r) => r.url().includes('/rest/v1/stories') && r.request().method() === 'POST');
      await tapIn(page, page.getByRole('button', { name: 'שיתוף' }));
      expect((await created).status(), 'POST stories').toBe(201);
      await page.waitForURL(/\/social/);

      // Открыть свою сторис по id (в вебе на iPhone тап по «הסטורי שלי» с активной сторис открывает создание новой —
      // проверка «свежая открывается из הסטורי שלי» относится к приложению iOS, здесь не проверяем).
      const found = await page.request.get(`${api.base}/rest/v1/stories?author_id=eq.${api.userId}&caption=eq.${encodeURIComponent(caption)}&select=id`, { headers: { apikey: api.apikey, Authorization: api.auth } });
      const rows = (await found.json()) as { id: string }[];
      expect(rows, 'сторис создана').toHaveLength(1);
      await page.goto(`/story/${rows[0].id}`);
      storyId = page.url().match(/\/story\/([0-9a-f-]{36})/)![1];
      await expect(page.getByText(caption, { exact: true })).toBeVisible();

      // Меню автора → окно подтверждения
      await tapIn(page, menuButton(page));
      const menu = page.getByRole('dialog').filter({ hasText: 'פעולות על הסטורי' });
      await expect(menu.getByRole('button', { name: /מחיקת הסטורי/ })).toBeVisible();
      await expect(menu.getByRole('button', { name: /דיווח/ })).toHaveCount(0);
      await tapIn(page, menu.getByRole('button', { name: /מחיקת הסטורי/ }));
      const confirm = page.getByRole('dialog').filter({ hasText: 'למחוק את הסטורי?' });
      await expect(confirm).toContainText('אי אפשר לשחזר אחרי מחיקה');
      await expect(confirm.getByRole('button', { name: 'מחיקה', exact: true })).toBeVisible();

      // «ביטול» — окно закрылось, та же сторис на экране (реджект r7: окно не закрывается само, сторис не уходит)
      await tapIn(page, confirm.getByRole('button', { name: 'ביטול', exact: true }));
      await expect(confirm).toHaveCount(0);
      expect(page.url()).toContain(`/story/${storyId}`);
      await expect(page.getByText(caption, { exact: true })).toBeVisible();

      // «מחיקה» — DELETE 2xx, сторис больше нет в базе
      await tapIn(page, menuButton(page));
      await tapIn(page, page.getByRole('button', { name: /מחיקת הסטורי/ }));
      const del = page.waitForResponse((r) => r.request().method() === 'DELETE' && r.url().includes(`/rest/v1/stories?id=eq.${storyId}`));
      await tapIn(page, page.getByRole('dialog').filter({ hasText: 'למחוק את הסטורי?' }).getByRole('button', { name: 'מחיקה', exact: true }));
      expect((await del).ok(), 'DELETE stories').toBeTruthy();
      const left = await page.request.get(`${api.base}/rest/v1/stories?id=eq.${storyId}&select=id`, { headers: { apikey: api.apikey, Authorization: api.auth } });
      expect(await left.json()).toEqual([]);
      storyId = '';
    } finally {
      // Запасная очистка: все сторис user4 с подписью этого прогона
      if (api && !page.isClosed()) {
        const q = storyId ? `id=eq.${storyId}` : `author_id=eq.${api.userId}&caption=eq.${encodeURIComponent(caption)}`;
        await page.request.delete(`${api.base}/rest/v1/stories?${q}`, { headers: { apikey: api.apikey, Authorization: api.auth }, failOnStatusCode: false });
      }
      await closeApp(page, 'user4');
    }
  });
});
